const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define geometry for Santa Cruz de la Sierra, east region
  const santaCruz = ee.Geometry.Point([-63.2, -17.8]).buffer(30000); // 30km radius

  // 2. Define time periods
  const period1986 = ee.Filter.date('1986-08-01', '1986-08-31');
  const period2001 = ee.Filter.date('2001-08-01', '2001-08-31');

  // 3. Function to mask clouds in Landsat 5
  function maskL5Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // 4. Function to mask clouds in Landsat 7
  function maskL7Clouds(image) {
    const qa = image.select('QA_PIXEL');
    const cloudMask = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloudMask);
  }

  // 5. Function to calculate NDVI and classify forest (NDVI > 0.6)
  function addForest(image) {
    const ndvi = image.normalizedDifference(['SR_B4', 'SR_B3']).rename('NDVI');
    const forest = ndvi.gt(0.6).rename('forest');
    return image.addBands([ndvi, forest]);
  }

  // 6. Get Landsat 5 data for 1986
  let col1986 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(santaCruz)
    .filter(period1986)
    .map(maskL5Clouds)
    .map(addForest);

  const size1986 = col1986.size().getInfo();
  console.log(`1986 Images found: ${size1986}`);

  if (size1986 === 0) {
    console.log('No data for August 1986');
    console.log('<answer>C1</answer>');
    return;
  }

  // 7. Get Landsat data for 2001 (try L7 first, then L5)
  let col2001 = ee.ImageCollection('LANDSAT/LE07/C02/T1_L2')
    .filterBounds(santaCruz)
    .filter(period2001)
    .map(maskL7Clouds)
    .map(addForest);

  let size2001 = col2001.size().getInfo();

  if (size2001 === 0) {
    col2001 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
      .filterBounds(santaCruz)
      .filter(period2001)
      .map(maskL5Clouds)
      .map(addForest);
    size2001 = col2001.size().getInfo();
  }

  console.log(`2001 Images found: ${size2001}`);

  if (size2001 === 0) {
    console.log('No data for August 2001');
    console.log('<answer>C1</answer>');
    return;
  }

  // 8. Create median composites
  const img1986 = col1986.median();
  const img2001 = col2001.median();

  // 9. Calculate forest area for 1986
  const forest1986 = img1986.select('forest');
  const stats1986 = forest1986.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: santaCruz,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const forestPixels1986 = stats1986['forest_sum'];
  const totalPixels1986 = stats1986['forest_count'];

  console.log(`1986 - Forest pixels: ${forestPixels1986}, Total valid: ${totalPixels1986}`);

  if (totalPixels1986 === 0 || totalPixels1986 === null) {
    console.log('No valid pixels for 1986 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 10. Calculate forest area for 2001
  const forest2001 = img2001.select('forest');
  const stats2001 = forest2001.reduceRegion({
    reducer: ee.Reducer.sum().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: santaCruz,
    scale: 3000,
    maxPixels: 1e9
  }).getInfo();

  const forestPixels2001 = stats2001['forest_sum'];
  const totalPixels2001 = stats2001['forest_count'];

  console.log(`2001 - Forest pixels: ${forestPixels2001}, Total valid: ${totalPixels2001}`);

  if (totalPixels2001 === 0 || totalPixels2001 === null) {
    console.log('No valid pixels for 2001 after masking');
    console.log('<answer>C2</answer>');
    return;
  }

  // 11. Validate calculations
  if (forestPixels1986 === null || forestPixels2001 === null) {
    console.log('Calculation failed - null result');
    console.log('<answer>C3</answer>');
    return;
  }

  // 12. Calculate forest cover percentages
  const forestCover1986 = (forestPixels1986 / totalPixels1986) * 100;
  const forestCover2001 = (forestPixels2001 / totalPixels2001) * 100;

  console.log(`Forest cover 1986: ${forestCover1986.toFixed(2)}%`);
  console.log(`Forest cover 2001: ${forestCover2001.toFixed(2)}%`);
  console.log(`Change: ${(forestCover2001 - forestCover1986).toFixed(2)}%`);

  // 13. Final answer
  if (forestCover2001 < forestCover1986) {
    console.log('<answer>A</answer>');
  } else {
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
